import numpy as np

def feature(current, candidates, tour, start):
    """Per-candidate: (distance-to-current) minus (distance to centroid of unvisited), but weighted by how much of the unvisited set is still a tight cluster around that centroid (compactness-gated)."""
    if len(candidates) == 0:
        return np.zeros(0)
    centroid = candidates.mean(axis=0)
    d_cent = np.linalg.norm(candidates - centroid, axis=1)
    d_cur = np.linalg.norm(candidates - current, axis=1)
    # spread of unvisited set: mean radius around centroid
    spread = float(np.mean(d_cent))
    # compactness in [0,1]: 1 when tight cluster, ->0 when widespread
    compact = 1.0 / (1.0 + 8.0 * spread)
    # when the remaining set is compact, strongly prefer the frontier (far from current,
    # close to centroid -> negative) ; when spread out, relax toward plain distance
    diff = (d_cur - d_cent) * (0.3 + compact)
    scale = diff.std()
    if scale < 1e-9:
        return np.zeros(len(candidates))
    return diff / (scale + 1e-9)

import numpy as np

def feature(current, candidates, tour, start):
    """Nearest-neighbour distance from each candidate to the rest of the unvisited set, minus its distance to the current city, normalised."""
    if len(candidates) == 0:
        return np.zeros(0)
    k = len(candidates)
    # pairwise distances among candidates
    diff = candidates[:, None, :] - candidates[None, :, :]
    dist = np.sqrt(np.einsum('ijk,ijk->ij', diff, diff))
    np.fill_diagonal(dist, np.inf)
    nn = dist.min(axis=1)  # distance to nearest other unvisited city
    d_cur = np.linalg.norm(candidates - current[None, :], axis=1)
    val = nn - d_cur
    scale = val.std()
    if scale < 1e-9:
        return np.zeros(k)
    return val / (scale + 1e-9)

import numpy as np

def feature(current, candidates, tour, start):
    """Fraction of other unvisited cities within 1.5x the mean nearest-neighbour distance of each candidate."""
    k = len(candidates)
    if k <= 1:
        return np.zeros(k)
    d = np.linalg.norm(candidates[:, None, :] - candidates[None, :, :], axis=2)
    np.fill_diagonal(d, np.inf)
    nn = d.min(axis=1)
    r = 1.5 * nn.mean()
    if not np.isfinite(r) or r <= 0:
        return np.zeros(k)
    counts = (d < r).sum(axis=1).astype(float)
    return counts / (k - 1)

