import numpy as np
import math

def feature(current, candidates, tour, start):
    """Negative exact optimal tail cost (current -> perm -> start) for the first city of the best permutation, gated to k <= 4, normalised."""
    k = len(candidates)
    if k > 4:
        return np.zeros(k)
    d_cur = np.linalg.norm(candidates - current, axis=1)
    d_start = np.linalg.norm(candidates - start, axis=1)
    best = np.full(k, np.inf)
    # enumerate permutations without itertools
    perms = [[]]
    for i in range(k):
        perms = [p + [i] for p in perms for i in range(k) if i not in p]
    for perm in perms:
        cost = d_cur[perm[0]]
        for i in range(k - 1):
            cost += np.linalg.norm(candidates[perm[i]] - candidates[perm[i + 1]])
        cost += d_start[perm[-1]]
        if cost < best[perm[0]]:
            best[perm[0]] = cost
    v = -best
    return v / (np.max(np.abs(v)) + 1e-9)

import numpy as np

def feature(current, candidates, tour, start):
    """Distance-to-current minus distance-to-unvisited-centroid, but each measured after projecting out the direction toward the start (so the pull toward the closing point is removed and only lateral spread matters)."""
    k = len(candidates)
    if k == 0:
        return np.zeros(0)
    centroid = candidates.mean(axis=0)
    # direction from current toward start (the closing pull), guarded
    v = start - current
    nv = np.linalg.norm(v)
    if nv < 1e-9:
        u = np.array([0.0, 0.0])
    else:
        u = v / nv
    # lateral (perpendicular) components: reject the closing direction
    def lateral(pts):
        proj = (pts - current[None, :]) @ u
        return (pts - current[None, :]) - proj[:, None] * u[None, :]
    lat_c = lateral(candidates)
    lat_cent = lateral(centroid[None, :])[0]
    d_cur_lat = np.linalg.norm(lat_c, axis=1)
    d_cent_lat = np.linalg.norm(lat_c - lat_cent[None, :], axis=1)
    diff = d_cur_lat - d_cent_lat
    scale = diff.std()
    if scale < 1e-9:
        return np.zeros(k)
    return diff / (scale + 1e-9)

import numpy as np

def feature(current, candidates, tour, start):
    """For each candidate: the gain in tour length if the current city were skipped, i.e. dist(prev, current) + dist(current, cand) - dist(prev, cand), where prev is the previous city in the tour (0 if none)."""
    k = len(candidates)
    if k == 0:
        return np.zeros(0)
    if len(tour) >= 2:
        prev = tour[-2]
    else:
        prev = start
    d_prev_cur = np.linalg.norm(current - prev)
    d_cur_cand = np.linalg.norm(candidates - current[None, :], axis=1)
    d_prev_cand = np.linalg.norm(candidates - prev[None, :], axis=1)
    # Positive when going prev->cand is cheaper than prev->cur->cand (i.e. we save by not detouring through current)
    saving = d_prev_cur + d_cur_cand - d_prev_cand
    scale = np.max(np.abs(saving))
    if scale < 1e-9:
        return np.zeros(k)
    return saving / (scale + 1e-9)

import numpy as np

def feature(current, candidates, tour, start):
    """Negative normalised farthest-other-remaining-city distance from each candidate (leftover-set radius)."""
    k = candidates.shape[0]
    if k <= 1:
        return np.zeros(k)
    diff = candidates[:, None, :] - candidates[None, :, :]
    D = np.sqrt((diff ** 2).sum(axis=-1))
    np.fill_diagonal(D, -np.inf)
    d_far = D.max(axis=1)
    return -(d_far / (d_far.max() + 1e-9))

