def feature(current, candidates, tour, start):
    """Centroid-gap measured on the remaining set excluding each candidate (leave-one-out centroid), minus distance to current, normalised."""
    k = len(candidates)
    if k <= 1:
        return np.zeros(k)
    total = candidates.sum(axis=0)
    # leave-one-out centroid: remove each candidate itself from the mean
    loo_centroid = (total[None, :] - candidates) / float(k - 1)
    d_loo = np.linalg.norm(candidates - loo_centroid, axis=1)
    d_cur = np.linalg.norm(candidates - current[None, :], axis=1)
    diff = d_cur - d_loo
    scale = diff.std()
    if scale < 1e-9:
        return np.zeros(k)
    return diff / (scale + 1e-9)

import numpy as np

def feature(current, candidates, tour, start):
    """For each candidate: gap in the length of the smallest edge leaving it when it is added to the visited set, vs the tour's current mean edge length — how much a 'cheap' insertion it is, normalised."""
    k = len(candidates)
    if k == 0:
        return np.zeros(0)
    # nearest-neighbour distance among the still-unvisited cities for each candidate
    diff = candidates[:, None, :] - candidates[None, :, :]
    dist = np.linalg.norm(diff, axis=2)
    np.fill_diagonal(dist, np.inf)
    nn_unvisited = dist.min(axis=1)
    # distance from each candidate to the current city
    d_cur = np.linalg.norm(candidates - current[None, :], axis=1)
    # a candidate whose nearest unvisited neighbour is close but which is far from current is a
    # "cluster anchor" — it isolates a cheap chunk. Combine: cheap local edge minus cost to reach it.
    score = d_cur - nn_unvisited
    scale = np.std(score)
    if scale < 1e-9:
        return np.zeros(k)
    return score / (scale + 1e-9)

import numpy as np

def feature(current, candidates, tour, start):
    """Signed angular alignment of each candidate's offset from the unvisited centroid with the direction from current to that centroid, scaled by the candidate's centroid-distance minus its current-distance profit."""
    k = len(candidates)
    if k == 0:
        return np.zeros(0)
    centroid = candidates.mean(axis=0)
    d_cent = np.linalg.norm(candidates - centroid, axis=1)
    d_cur = np.linalg.norm(candidates - current[None, :], axis=1)
    profit = d_cur - d_cent  # same thread: prefer near-current, far-from-centre
    # outward radial direction from centroid to candidate
    off = candidates - centroid[None, :]
    norm_off = np.linalg.norm(off, axis=1)
    # direction from current to centroid (the "sweep" direction)
    sweep = centroid - current
    ns = np.linalg.norm(sweep)
    if ns < 1e-9 or norm_off.max() < 1e-9:
        return np.zeros(k)
    cos_align = (off @ sweep) / (norm_off * ns + 1e-12)
    # combine: profitable candidates that lie outward along the sweep direction
    val = profit * (0.5 + 0.5 * cos_align) / (norm_off + 1e-9)
    s = np.std(val)
    if s < 1e-9:
        return np.zeros(k)
    return val / (s + 1e-9)

import numpy as np

def feature(current, candidates, tour, start):
    """For each candidate: distance to its nearest unvisited neighbor (excluding itself) minus its distance to current, normalised — prefers candidates that are isolated (would be costly to reach later) rather than those crowding a cluster."""
    k = len(candidates)
    if k <= 1:
        return np.zeros(k)
    # pairwise distances among candidates
    diff = candidates[:, None, :] - candidates[None, :, :]
    dmat = np.sqrt((diff ** 2).sum(axis=2))
    np.fill_diagonal(dmat, np.inf)  # exclude self
    nn = dmat.min(axis=1)  # nearest unvisited neighbor distance
    d_cur = np.linalg.norm(candidates - current[None, :], axis=1)
    # isolation penalty: large nn means isolated -> should be visited sooner (deferred cost)
    # combine: prefer isolated (large nn) and near current (small d_cur)
    score = nn - d_cur
    scale = score.std()
    if scale < 1e-9:
        return np.zeros(k)
    return score / (scale + 1e-9)

import numpy as np

def feature(current, candidates, tour, start):
    """1 for hops longer than twice the tour's running median edge length (binary gate), 0 otherwise."""
    k = len(candidates)
    if k == 0:
        return np.zeros(0)
    d_cur = np.linalg.norm(candidates - current[None, :], axis=1)
    s = 0.0
    if len(tour) >= 3:
        e = np.linalg.norm(np.diff(tour, axis=0), axis=1)
        s = float(np.median(e))
    if s <= 1e-9 and k >= 2:
        G = np.linalg.norm(candidates[:, None, :] - candidates[None, :, :], axis=2)
        np.fill_diagonal(G, np.inf)
        s = float(np.mean(G.min(axis=1)))
    if s <= 1e-9:
        return np.zeros(k)
    return -(d_cur > 2.0 * s).astype(float)

