def feature(current, candidates, tour, start):
    """For each candidate: distance-to-current minus distance to the centroid of the OTHER unvisited cities (leave-one-out), but the centroid is pulled toward the start city as the tour progresses, so late in the tour the frontier is anchored near the start."""
    k = len(candidates)
    if k == 0:
        return np.zeros(0)
    if k == 1:
        return np.zeros(1)
    # leave-one-out centroid of the other unvisited cities
    total = candidates.sum(axis=0)
    loo_centroid = (total[None, :] - candidates) / float(k - 1)   # (k, 2)
    d_loo = np.linalg.norm(candidates - loo_centroid, axis=1)
    d_cur = np.linalg.norm(candidates - current[None, :], axis=1)
    # progress in [0,1): fraction of cities already visited
    m = len(tour)
    n = m + k
    progress = m / float(n) if n > 0 else 0.0
    # anchor point moves from LOO centroid toward the start city as the tour progresses
    anchor = (1.0 - progress) * loo_centroid + progress * start[None, :]
    d_anchor = np.linalg.norm(candidates - anchor, axis=1)
    diff = d_cur - d_anchor
    scale = diff.std()
    if scale < 1e-9:
        return np.zeros(k)
    return diff / (scale + 1e-9)

