def feature(current, candidates, tour, start):
    """Angular gap left open: for each candidate, the sine of the angle it subtends at the current city relative to the direction toward the start, preferring candidates that close the loop (small angular deviation from the start direction), scaled by proximity."""
    d_cur = np.linalg.norm(candidates - current[None, :], axis=1)
    if len(candidates) == 0:
        return np.zeros(0)
    # direction to each candidate
    vec_c = candidates - current[None, :]
    # direction to start
    vec_s = start - current
    ns = np.linalg.norm(vec_s)
    nc = d_cur + 1e-9
    if ns < 1e-9:
        # already at start: use direction of first visited (tour[1] if exists) else zero
        if len(tour) > 1:
            vec_s = tour[1] - tour[0]
            ns = np.linalg.norm(vec_s)
        if ns < 1e-9:
            return np.zeros(len(candidates))
    cosang = (vec_c @ vec_s) / (nc * ns + 1e-12)
    cosang = np.clip(cosang, -1.0, 1.0)
    # angular deviation from start direction: 1 - cos = 0 when aligned
    ang = 1.0 - cosang
    # weight by how close the candidate is (fraction of distance to start covered)
    frac = d_cur / (d_cur + ns + 1e-9)
    return -ang * (1.0 - frac)

