def feature(current, candidates, tour, start):
    """Negative standardised weighted Held-Karp tail cost (closing leg x3) for k in [8,10], zeros otherwise."""
    k = len(candidates)
    if k < 8 or k > 10:
        return np.zeros(k)

    pts = np.vstack([candidates, start])  # last index k is start
    diff = pts[:, None, :] - pts[None, :, :]
    D = np.sqrt((diff ** 2).sum(axis=2))

    full = (1 << k) - 1
    INF = 1e18
    B = np.full((1 << k, k), INF)
    for j in range(k):
        B[1 << j, j] = 3.0 * D[j, k]

    for mask in range(1, full + 1):
        for j in range(k):
            if not (mask & (1 << j)):
                continue
            bj = B[mask, j]
            if bj >= INF:
                continue
            for i in range(k):
                if mask & (1 << i):
                    continue
                nm = mask | (1 << i)
                v = bj + D[j, i]
                if v < B[nm, i]:
                    B[nm, i] = v

    T = B[full, :]
    mu = T.mean()
    sd = T.std()
    return -((T - mu) / (sd + 1e-9))

