def feature(current, candidates, tour, start):
    """Perimeter growth of the visited-set convex hull when each candidate is inserted, divided by hull perimeter."""
    pts = np.asarray(tour, dtype=float).reshape(-1, 2)
    cand = np.asarray(candidates, dtype=float).reshape(-1, 2)
    k = cand.shape[0]
    if k == 0:
        return np.zeros(0)

    # Monotone chain convex hull over the visited cities.
    order = np.lexsort((pts[:, 1], pts[:, 0]))
    P = pts[order]
    # Deduplicate consecutive identical points.
    keep = np.ones(len(P), dtype=bool)
    if len(P) > 1:
        keep[1:] = np.any(P[1:] != P[:-1], axis=1)
    P = P[keep]
    n = len(P)

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    if n <= 2:
        hull = P
    else:
        lower = []
        for p in P:
            while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
                lower.pop()
            lower.append(p)
        upper = []
        for p in P[::-1]:
            while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
                upper.pop()
            upper.append(p)
        hull = np.array(lower[:-1] + upper[:-1], dtype=float)

    h = len(hull)

    if h == 1:
        h0 = hull[0]
        growth = 2.0 * np.linalg.norm(cand - h0, axis=1)
        perim = 0.0
    else:
        # Consecutive hull vertex pairs including wrap-around.
        A = hull
        B = np.roll(hull, -1, axis=0)
        edge_len = np.linalg.norm(B - A, axis=1)  # shape (h,)
        perim = float(edge_len.sum())
        # Distances from each candidate to each hull vertex: (k, h)
        dA = np.linalg.norm(cand[:, None, :] - A[None, :, :], axis=2)
        dB = np.linalg.norm(cand[:, None, :] - B[None, :, :], axis=2)
        growth_edges = dA + dB - edge_len[None, :]  # (k, h)
        growth = growth_edges.min(axis=1)

    return growth / (perim + 1e-9)

