def feature(current, candidates, tour, start):
    """Distance to the current city plus the candidate's distance to the unvisited-set centroid, but only measured along the direction from current toward the centroid: rewards candidates that lie 'ahead' of the walk's centre of mass while staying close."""
    k = len(candidates)
    if k == 0:
        return np.zeros(0)
    centroid = candidates.mean(axis=0)
    d_cur = np.linalg.norm(candidates - current[None, :], axis=1)
    # unit direction from current to the unvisited centroid
    dir_vec = centroid - current
    dir_norm = np.linalg.norm(dir_vec)
    if dir_norm < 1e-9:
        # degenerate: fall back to plain near-current preference
        scale = d_cur.std()
        if scale < 1e-9:
            return np.zeros(k)
        return -(d_cur - d_cur.mean()) / (scale + 1e-9)
    u = dir_vec / dir_norm
    # projection of each candidate onto that direction, measured from current
    proj = (candidates - current[None, :]) @ u          # positive = ahead of current
    # perpendicular (lateral) offset from the ray
    lateral = np.sqrt(np.maximum(d_cur ** 2 - proj ** 2, 0.0))
    # a candidate is good if it lies ahead (large proj) and near the ray (small lateral)
    score = proj - lateral
    scale = score.std()
    if scale < 1e-9:
        return np.zeros(k)
    return (score - score.mean()) / (scale + 1e-9)

