def feature(current, candidates, tour, start):
    """Angular sweep: for each candidate, the signed angle (cosine) between the current direction of travel and the direction to the candidate, times a decay in distance-to-current."""
    k = len(candidates)
    if k == 0:
        return np.zeros(0)
    # direction of travel: from previous city to current (tour[-2] -> tour[-1])
    if len(tour) >= 2:
        heading = current - tour[-2]
    else:
        heading = current - start
    hnorm = np.linalg.norm(heading)
    if hnorm < 1e-9:
        # no heading: fall back to closeness to current
        d_cur = np.linalg.norm(candidates - current[None, :], axis=1)
        return -d_cur / (d_cur.max() + 1e-9)
    h = heading / hnorm
    vecs = candidates - current[None, :]
    d = np.linalg.norm(vecs, axis=1)
    safe = d > 1e-9
    cos = np.zeros(k)
    cos[safe] = (vecs[safe] @ h) / d[safe]
    # angular alignment, weighted so far-away candidates matter less
    weight = 1.0 / (1.0 + d)
    score = cos * weight
    s = score.std()
    if s < 1e-9:
        return np.zeros(k)
    return score / (s + 1e-9)

import numpy as np

def feature(current, candidates, tour, start):
    """Centred product of standardised distance-to-current and standardised leave-one-out nearest-neighbour distance among candidates, clipped to [-1, 1]."""
    current = np.asarray(current, dtype=float)
    candidates = np.asarray(candidates, dtype=float)
    k = candidates.shape[0]
    if k == 0:
        return np.zeros(0)

    # distance from current to each candidate
    d_cur = np.sqrt(np.sum((candidates - current) ** 2, axis=1))

    # leave-one-out nearest-neighbour distance among candidates
    if k == 1:
        s = np.zeros(1)
    else:
        diff = candidates[:, None, :] - candidates[None, :, :]
        D = np.sqrt(np.sum(diff ** 2, axis=2))
        np.fill_diagonal(D, np.inf)
        s = np.min(D, axis=1)

    def standardise(v):
        sd = np.std(v)
        if sd == 0 or not np.isfinite(sd):
            return np.zeros_like(v)
        return (v - np.mean(v)) / sd

    zd = standardise(d_cur)
    zs = standardise(s)
    return np.clip(zd * zs, -1.0, 1.0)
